void unit_test_quickSort_unsorted_array_full_sort(void) {
    // Setup: create an unsorted array
    const int input_values[] = {5, 2, 9, 1, 5, 6};
    const int expected_sorted[] = {1, 2, 5, 5, 6, 9};
    const int size = 6;
    int *arr = create_int_test_array(input_values, size);

    // Test: sort the entire array
    quickSort(arr, 0, size - 1);

    // Assertions: array is sorted and matches expected
    assert_array_sorted(arr, size);
    assert_array_equal(arr, expected_sorted, size);

    // Cleanup
    cleanup_int_test_array(arr);
}
